// 实战技巧：
// 1. 上下文压缩：每 10 轮总结一次关键信息
// 2. 工具结果截断：长输出保留前 500 + 后 200 字符
// 3. 上下文搜索：让 agent 主动搜索历史而非全量加载

// 合规保证：分类器看不到工具结果
// 攻击向量：网页包含 "ignore previous instructions"
// 分类器仅基于工具调用本身（命令、参数）判断
// 不受工具输出影响

const response = await anthropic.messages.create({
  model: "claude-sonnet-4.5",
  max_tokens: 16000,
  thinking: { type: "enabled", budget_tokens: 5000 },
  messages: [{ role: "user", content: prompt }]
});

// Low effort: 快速回答，节省成本
claude --effort low "What is 2+2?"

// High effort: 深度推理，适合复杂问题
claude --effort high "Debug this race condition"

// .claude/settings.json
{
  "hooks": {
    "PreToolUse": [{
      "matcher": "Bash",
      "hooks": [{"type": "shell", "command": "echo"}]
    }]
  }
}

{
  "guides": ["CLAUDE.md", "rules"],
  "sensors": ["tests", "linters", "type checkers", "AI code review"]
}
